const grid = window.grid;
const selectedIds = grid.getSelectedItemIds();
if (selectedIds.length !== 1) {
	return;
}

const selectedItemId = selectedIds[0];
const rows = grid._grid.rows;
const relatedId = rows.get(selectedItemId, 'related_id');
if (relatedId) {
	window.showRelatedItemById(selectedItemId);
} else {
	window.showRelationshipById(selectedItemId);
}
